add_action( 'woocommerce_register_form', 'perfectpixel_registration_privacy_checkbox', 30 );
add_filter( 'woocommerce_registration_errors', 'perfectpixel_registration_privacy_validate', 10, 3 );
add_action( 'woocommerce_created_customer', 'perfectpixel_registration_privacy_save' );

function perfectpixel_registration_privacy_checkbox() {
	$url  = get_privacy_policy_url();
	$link = $url ? '<a href="' . esc_url( $url ) . '" target="_blank">' . esc_html( '{{privacy_consent_link}}' ) . '</a>' : esc_html( '{{privacy_consent_link}}' );
	echo '<p class="form-row validate-required"><label class="woocommerce-form__label woocommerce-form__label-for-checkbox checkbox"><input type="checkbox" class="woocommerce-form__input woocommerce-form__input-checkbox" name="perfectpixel_privacy_consent" value="1" required> <span>' . str_replace( '{privacy_policy}', $link, esc_html( '{{privacy_consent_text}}' ) ) . '</span> <span class="required">*</span></label></p>';
}

function perfectpixel_registration_privacy_validate( $errors, $username, $email ) {
	if ( empty( $_POST['perfectpixel_privacy_consent'] ) && ! is_checkout() ) {
		$errors->add( 'perfectpixel_privacy_consent', '{{privacy_consent_error}}' );
	}
	return $errors;
}

function perfectpixel_registration_privacy_save( $customer_id ) {
	if ( ! empty( $_POST['perfectpixel_privacy_consent'] ) ) {
		update_user_meta( $customer_id, 'perfectpixel_privacy_consent', current_time( 'mysql' ) );
	}
}
